import{_ as u,a0 as o,w as r,s as a,ao as s,I as n,a1 as e,A as l,x as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"可以快速保存、访问和粘贴文本片段的Unity漂亮工具 | LCTT x X-CMD","titleTemplate":false,"description":"可以快速保存、访问和粘贴文本片段的Unity漂亮工具 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"可以快速保存、访问和粘贴文本片段的Unity漂亮工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"可以快速保存、访问和粘贴文本片段的Unity漂亮工具 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Save, Access And Quickly Paste Text Snippets With This Nifty Unity Launcher Tool","title":"可以快速保存、访问和粘贴文本片段的Unity漂亮工具","tag":"201311","desc":""},"relativePath":"201311/Save, Access And Quickly Paste Text Snippets With This Nifty Unity Launcher Tool.md","filePath":"[post].md"}'),d={name:"201311/Save, Access And Quickly Paste Text Snippets With This Nifty Unity Launcher Tool.md"};function T(m,t,y,f,S,x){const p=o("Link");return r(),a("div",null,[t[16]||(t[16]=s('<h1 id="可以快速保存、访问和粘贴文本片段的unity漂亮工具" tabindex="-1">可以快速保存、访问和粘贴文本片段的Unity漂亮工具 <a class="header-anchor" href="#可以快速保存、访问和粘贴文本片段的unity漂亮工具" aria-label="Permalink to “可以快速保存、访问和粘贴文本片段的Unity漂亮工具”">​</a></h1><p><strong>反复键入特定的信息 - 如电子邮件地址或家庭地址，详细的终端命令，及时发送用户喜爱的电视节目的资讯 - 可是件苦差事。</strong></p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/10/Screen-Shot-2013-10-31-at-13.04.jpg" alt=""><em>Snippets – 方便的访问存储的文本的方法</em></p><p>谢天谢地，这个世界上有一些工具可以帮助我们（做这些事儿）。</p><p><em>‘Snippets’</em> 就是Unity中这种组件之一。 这是一个简单的启动程序小工具，它让你在一个文件中保存和存储摘下来的内容，然后当你需要的时候从Unity的一个快速列表里复制到剪贴板。</p><p>在某些人把他的内裤扔到我的脸上之前，我得说Snippets不是唯一的这种工具，它甚至不是第一个提供这一系列功能的。但是它独特的是通过Unity启动器来提供这一系列功能。</p><p>这个软件具功能不错又足够简单，提供以下功能:</p><ul><li>添加、访问存储在txt文件中的文本段</li><li>在快速列表里查看保存的文本段</li><li>点击文本段就可以复制到剪贴板</li><li>提供了把剪贴板中的内容保存到txt文件的选项</li></ul><p>尽管它不是一个“智能”的剪贴板管理工具 – 它只是列出了你特别添加的项目；它不会列出你最近的剪贴板项目历史，但仍然是一个非常方便的小工具。</p><p>###怎样为Unity安装Snippets###</p><p>想要使用这个漂亮的启动器项目，你需要先安装一个命令行剪贴板工具XClip。点击下面的按钮（链接）从软件中心安装。</p>',11)),n("ul",null,[n("li",null,[e(p,{href:"apt://xclip"},{default:l(()=>[...t[0]||(t[0]=[i("点击以在Ubuntu里安装XClip",-1)])]),_:1})])]),t[17]||(t[17]=n("p",null,"下一步，下载下面的‘Snippets’压缩文件。这包含了剩余所有的使用这个应用所需要的东西。",-1)),n("ul",null,[n("li",null,[e(p,{href:"https://www.dropbox.com/s/ha6lngizmz78srv/snippets%20by%20stinkeye.tar.gz"},{default:l(()=>[...t[1]||(t[1]=[i("下载‘Snippets’Unity启动器",-1)])]),_:1})])]),t[18]||(t[18]=s(`<p>当这个压缩文件下完之后你就可以解压了。进入生成的文件夹，然后按Ctrl+H显示隐藏的文件。移动文件夹‘.snippets-launcher‘到你的主文件夹中。<strong>如果不这么做，这个组件将无法正常工作。</strong></p><p>下一步是安装启动器项目。这是被一个你刚搬到文件夹里面的脚本关照的，但它不具有可执行的权限（需要安装），因此，我们首先需要关照它一下。</p><p>打开一个新的终端窗口在里面小心的键入下面的命令：</p><pre><code>cd .snippets-launcher/ &amp;&amp; chmod +x snippets.sh
./snippets.sh
</code></pre><p>就是这样；Snippets应该已经整装待发了。打开Unity Dash搜索Snippets然后把它拖到启动器上去：</p><ul><li>左键点击启动器打开可以添加你的文本段的文本文件</li><li>右键点击启动器上的项目打开快速列表</li></ul><p>快速列表里的选项:</p><ul><li>左键点击文本段以添加到剪贴板</li><li>左键点击“日期”可以复制当前日期</li><li>点击“添加剪贴板内容”可以把当前剪贴板中的内容加入到.txt文件中（译注：实际上保存的文本是存储在一个文本文件中）</li><li>在添加一个项目到.txt文件后点击“更新启动器”</li></ul>`,8)),n("p",null,[t[3]||(t[3]=i("更多关于这个懒人的工具信息尽在",-1)),e(p,{href:"http://ubuntuforums.org/showthread.php?t=2184916"},{default:l(()=>[...t[2]||(t[2]=[i("Ubuntu论坛",-1)])]),_:1}),t[4]||(t[4]=i("，在那里它的开发者，“Stinkeye”,会很高兴地提供帮助。",-1))]),t[19]||(t[19]=n("hr",null,null,-1)),n("p",null,[t[6]||(t[6]=i("via: ",-1)),e(p,{href:"http://www.omgubuntu.co.uk/2013/10/unity-launcher-clipboard-snippets-item"},{default:l(()=>[...t[5]||(t[5]=[i("http://www.omgubuntu.co.uk/2013/10/unity-launcher-clipboard-snippets-item",-1)])]),_:1})]),n("p",null,[t[9]||(t[9]=i("译者：",-1)),e(p,{href:"https://github.com/%E8%AF%91%E8%80%85ID"},{default:l(()=>[...t[7]||(t[7]=[i("crowner",-1)])]),_:1}),t[10]||(t[10]=i(" 校对：",-1)),e(p,{href:"https://github.com/wxy"},{default:l(()=>[...t[8]||(t[8]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=i("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[11]||(t[11]=[i("LCTT",-1)])]),_:1}),t[14]||(t[14]=i(" 原创翻译，",-1)),e(p,{href:"http://linux.cn/"},{default:l(()=>[...t[12]||(t[12]=[i("Linux中国",-1)])]),_:1}),t[15]||(t[15]=i(" 荣誉推出",-1))])])}const U=u(d,[["render",T]]);export{w as __pageData,U as default};
